import { describe, expect, it } from 'vitest';
import { scan } from '../../src/core/scan.js';
import { isGeneratedSource } from '../../src/core/generated.js';
import { longJsFunction, onlyRule, useProjects } from '../helpers/project.js';

const projects = useProjects();
const config = onlyRule('SC-MET-001', { maxLines: 3 });

describe('generated files (US-001, found in eShop)', () => {
  it.each([
    [
      'C# auto-generated',
      '// <auto-generated>\n//   Generated by the protocol buffer compiler.\n// </auto-generated>\nclass A { }\n',
    ],
    [
      'C# designer',
      '//------------------------------------------------------------------------------\n// <auto-generated>\n//     This code was generated by a tool.\n',
    ],
    [
      'protobuf Python',
      '# -*- coding: utf-8 -*-\n# Generated by the protocol buffer compiler.  DO NOT EDIT!\nimport x\n',
    ],
    [
      'C# with a byte-order mark before the notice',
      `${String.fromCharCode(0xfeff)}// <auto-generated>\nclass A { }\n`,
    ],
    ['JavaScript @generated', '/**\n * @generated\n */\nexport const a = 1;\n'],
    ['Go-style notice', '// Code generated by mockgen. DO NOT EDIT.\nexport {};\n'],
  ])('recognizes %s from its header', (_name, source) => {
    expect(isGeneratedSource(source)).toBe(true);
  });

  it.each([
    ['plain code', 'export const a = 1;\n'],
    [
      'a note far below the header',
      `${'// x\n'.repeat(40)}// this file is automatically generated by hand\n`,
    ],
    ['a word that only looks similar', '// Regenerated nightly by the team\nexport {};\n'],
    ['an empty file', ''],
    [
      'a comment that talks about the notices (this tool recognizes them)',
      '/**\n * The notices tools put at the top: `<auto-generated>` (C#), `@generated`, and\n * "Code generated ... DO NOT EDIT".\n */\nexport const a = 1;\n',
    ],
    ['a string that holds a notice', "const header = '// <auto-generated>';\nexport {};\n"],
  ])('does not take %s for generated code', (_name, source) => {
    expect(isGeneratedSource(source)).toBe(false);
  });

  it('leaves a generated file out of the rules, says so, and still checks the rest', async () => {
    const folder = await projects.create({
      'gen.js': `/* @generated */\n${longJsFunction('made', 8)}`,
      'own.js': longJsFunction('written', 8),
    });

    const result = await scan(folder, { config });

    expect(result.findings.map((f) => f.path)).toEqual(['own.js']);
    expect(result.files.map((f) => f.path)).toEqual(['own.js']);
    expect(result.filesScanned).toBe(2);
    expect([...result.notes]).toContain(
      '1 generated file was not analyzed (its header says it was generated).',
    );
  });
});
